/**
 * 负责机械狼的学习模板、所属槽安装、模式／刀资源提交和玩家投影。输入为原角色、状态与日次；
 * 输出保留原学习、模式、刀权字段以及存储引用，公开 DTO 类型独立归公共契约。
 * 未付提交可传捕获拒绝回调，在原 getter／参数读取后且首写前调用；无回调仍是原纯数据转换，不授予行动。
 * 模板创建不克隆其他玩家库存；本模块只写 mechanical_wolf 及其资源，不替换角色容器或授予请求许可。
 * 实际开夜才武装枪和处理首刀过期；提交按原字段顺序，异常不回滚此前状态。
 */
import type {
  MechanicalMode,
  MechanicalSkill,
  MechanicalLearning,
  MechanicalState,
  MechanicalReadSkill,
  MechanicalReadLearning,
  MechanicalReadState,
} from "@ai-werewolf-arena/game-contract";

import type { PlayerMechanicalState } from "@ai-werewolf-arena/game-contract/player-state-views";
import type { InspectionResult, RoleId } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { EntityId } from "../../../../core/domain/identity";
import { copyAbilityData } from "../abilities";
import { createLearnedNativeGun, armMechanicalNativeGun } from "../native-death-gun-resources";

export function freshMechanicalState(): MechanicalState {
  return {
    learned: null,
    mimicClosedDay: null,
    mode: null,
    hasInheritedKnife: false,
    firstKnifeNight: null,
    skillClosedDay: null,
  };
}
/** 从所属槽返回原存储引用；类型只读不等于复制或运行时冻结，写入仍由具名提交函数负责。 */
export function getMechanicalState(
  role: RoleComponent | undefined,
): MechanicalReadState | undefined {
  return (role as { readonly privateState: { readonly mechanical_wolf?: unknown } } | undefined)
    ?.privateState.mechanical_wolf as MechanicalReadState | undefined;
}
export function setMechanicalState(
  role: RoleComponent,
  state: MechanicalState,
): MechanicalReadState {
  const owned = copyAbilityData(state);
  (role.privateState as { mechanical_wolf: MechanicalState }).mechanical_wolf = owned;
  return owned;
}
export function mechanicalLearning(
  targetId: EntityId,
  role: RoleId,
  day: number,
): MechanicalLearning {
  let skill: MechanicalSkill;
  switch (role) {
    case "villager":
      skill = { kind: "villager" };
      break;
    case "psychic":
      skill = { kind: "inspection", history: [] };
      break;
    case "witch":
      skill = { kind: "poison", remaining: 1 };
      break;
    case "guard":
      skill = { kind: "guard", lastTarget: null, lastGuardDay: null };
      break;
    case "hunter":
      skill = createLearnedNativeGun();
      break;
    case "wolf":
      skill = { kind: "wolf", extraKnife: "available" };
      break;
    default:
      throw new Error("mechanical_learning_role_not_supported");
  }
  return { targetId, role, day, readyOnNight: day + 1, skill };
}

/** 开局／死亡检查点调用此处一次提交继承字段；后续刀权资格和事实发布仍由原调用方负责。 */
export function recordMechanicalInheritance(state: MechanicalReadState, day: number): boolean {
  if (state.hasInheritedKnife) return false;
  (state as { hasInheritedKnife: boolean }).hasInheritedKnife = true;
  (state as { firstKnifeNight: number | null }).firstKnifeNight = Math.max(2, day + 1);
  return true;
}

export function canMechanicalMimic(state: MechanicalReadState, day: number): boolean {
  return (
    day >= 1 &&
    state.learned === null &&
    (state.mimicClosedDay === null || state.mimicClosedDay < day)
  );
}

/** 合法等待只关闭本夜学习机会，保留整局一次的学习库存。 */
export function closeMechanicalMimic(state: MechanicalReadState, day: number, mayCommit?: () => boolean): boolean {
  if (!canMechanicalMimic(state, day)) return false;
  if (mayCommit && !mayCommit()) return false;
  (state as { mimicClosedDay: number | null }).mimicClosedDay = day;
  return true;
}

export function learnMechanicalRole(
  state: MechanicalReadState,
  targetId: EntityId,
  role: RoleId,
  day: number,
  mayCommit?: () => boolean,
): boolean {
  if (!canMechanicalMimic(state, day)) return false;
  const learned = mechanicalLearning(targetId, role, day);
  if (
    learned.skill.kind === "wolf" &&
    state.firstKnifeNight !== null &&
    day >= state.firstKnifeNight
  ) {
    (learned.skill as { extraKnife: "available" | "spent" | "expired" }).extraKnife = "expired";
  }
  // 原资格和模板／首刀 getter 已读完；回调只否决首写，之后保持两字段完成前缀。
  if (mayCommit && !mayCommit()) return false;
  (state as { learned: MechanicalReadState["learned"] }).learned = learned;
  (state as { mimicClosedDay: number | null }).mimicClosedDay = day;
  return true;
}

/** 进入实际夜才武装被动枪，并将已经过去的首刀窗口标为过期，不能靠日次跳转补刀。 */
export function advanceMechanicalNight(state: MechanicalReadState, day: number): void {
  const learned = state.learned;
  if (!learned) return;
  armMechanicalNativeGun(learned, day);
  if (
    learned.skill.kind === "wolf" &&
    learned.skill.extraKnife === "available" &&
    state.firstKnifeNight !== null &&
    day > state.firstKnifeNight
  ) {
    (learned.skill as { extraKnife: "available" | "spent" | "expired" }).extraKnife = "expired";
  }
}

export function canSelectMechanicalMode(state: MechanicalReadState, day: number): boolean {
  return day >= 2 && (state.mode === null || state.mode.day < day);
}

/** 等待沿用技能模式选择；本夜第二次选择被拒，不重写第一次模式。 */
export function selectMechanicalMode(
  state: MechanicalReadState,
  day: number,
  mode: MechanicalMode,
  mayCommit?: () => boolean,
): boolean {
  if (!canSelectMechanicalMode(state, day)) return false;
  if (mayCommit && !mayCommit()) return false;
  (state as { mode: MechanicalReadState["mode"] }).mode = { day, kind: mode };
  const learned = state.learned;
  if (
    mode === "skill" &&
    state.firstKnifeNight === day &&
    learned?.skill.kind === "wolf" &&
    learned.skill.extraKnife === "available"
  ) {
    (learned.skill as { extraKnife: "available" | "spent" | "expired" }).extraKnife = "expired";
  }
  return true;
}

export function mechanicalSkillForNight(
  state: MechanicalReadState,
  day: number,
): MechanicalReadSkill | undefined {
  if (
    day < 2 ||
    state.mode?.day !== day ||
    state.mode.kind !== "skill" ||
    !state.learned ||
    state.learned.readyOnNight > day ||
    (state.skillClosedDay !== null && state.skillClosedDay >= day)
  )
    return undefined;
  return state.learned.skill;
}

export function closeMechanicalSkill(state: MechanicalReadState, day: number, mayCommit?: () => boolean): boolean {
  if (!mechanicalSkillForNight(state, day)) return false;
  if (mayCommit && !mayCommit()) return false;
  (state as { skillClosedDay: number | null }).skillClosedDay = day;
  return true;
}

/** 调用方另行核对当前唯一活狼的刀权及原模式许可；本字段查询不授予出刀资格。 */
export function mechanicalKnifeSelected(state: MechanicalReadState, day: number): boolean {
  return (
    day >= 2 &&
    state.hasInheritedKnife &&
    state.firstKnifeNight !== null &&
    day >= state.firstKnifeNight &&
    state.mode?.day === day &&
    state.mode.kind === "kill"
  );
}

export function canMechanicalExtraKnife(state: MechanicalReadState, day: number): boolean {
  const learned = state.learned;
  return (
    mechanicalKnifeSelected(state, day) &&
    state.firstKnifeNight === day &&
    learned !== null &&
    learned.readyOnNight <= day &&
    learned.skill.kind === "wolf" &&
    learned.skill.extraKnife === "available"
  );
}

/** 按相邻实际夜与目标编号判重复守护，同编号复活不会清除该历史；两字段按原顺序写入。 */
export function chooseMechanicalGuard(
  skill: Extract<MechanicalReadSkill, { kind: "guard" }>,
  targetId: EntityId | null,
  day: number,
): { failed: boolean };
export function chooseMechanicalGuard(
  skill: Extract<MechanicalReadSkill, { kind: "guard" }>,
  targetId: EntityId | null,
  day: number,
  mayCommit: () => boolean,
): { failed: boolean } | null;
export function chooseMechanicalGuard(
  skill: Extract<MechanicalReadSkill, { kind: "guard" }>,
  targetId: EntityId | null,
  day: number,
  mayCommit?: () => boolean,
): { failed: boolean } | null {
  const failed =
    targetId !== null && skill.lastTarget === targetId && skill.lastGuardDay === day - 1;
  // 守护历史 getter 可以执行代码；空返回仅是未付拒绝，不伪造守护成功或惩罚。
  if (mayCommit && !mayCommit()) return null;
  (skill as { lastTarget: EntityId | null }).lastTarget = targetId;
  (skill as { lastGuardDay: number | null }).lastGuardDay = day;
  return { failed };
}

/** 玩家投影逐字段列出知识和资源摘要；以后新增的全局调试字段不会自动成为玩家输入。 */
export function projectMechanicalState(state: MechanicalReadState): PlayerMechanicalState {
  const learned = state.learned;
  let skill: MechanicalSkill | undefined;
  if (learned)
    switch (learned.skill.kind) {
      case "villager":
        skill = { kind: "villager" };
        break;
      case "inspection":
        skill = {
          kind: "inspection",
          history: learned.skill.history.map((report) => ({
            day: report.day,
            targetId: report.targetId,
            result: { kind: "role", role: report.result.role },
          })),
        };
        break;
      case "poison":
        skill = { kind: "poison", remaining: learned.skill.remaining };
        break;
      case "guard":
        skill = {
          kind: "guard",
          lastTarget: learned.skill.lastTarget,
          lastGuardDay: learned.skill.lastGuardDay,
        };
        break;
      case "hunter":
        skill = { kind: "hunter", canShoot: learned.skill.canShoot, armed: learned.skill.armed };
        break;
      case "wolf":
        skill = { kind: "wolf", extraKnife: learned.skill.extraKnife };
        break;
    }
  return {
    learned:
      learned && skill
        ? {
            targetId: learned.targetId,
            role: learned.role,
            day: learned.day,
            readyOnNight: learned.readyOnNight,
            skill,
          }
        : null,
    mimicClosedDay: state.mimicClosedDay,
    mode: state.mode ? { day: state.mode.day, kind: state.mode.kind } : null,
    hasInheritedKnife: state.hasInheritedKnife,
    firstKnifeNight: state.firstKnifeNight,
    skillClosedDay: state.skillClosedDay,
  };
}

/** 调用方保留查验与当前性检查；先读取原历史容器，再读取 target.id 并追加一行。 */
export function recordMechanicalInspection(
  skill: Extract<MechanicalReadSkill, { kind: "inspection" }>,
  day: number,
  target: { readonly id: EntityId },
  result: Extract<InspectionResult, { kind: "role" }>,
): void;
export function recordMechanicalInspection(
  skill: Extract<MechanicalReadSkill, { kind: "inspection" }>,
  day: number,
  target: { readonly id: EntityId },
  result: Extract<InspectionResult, { kind: "role" }>,
  mayCommit: () => boolean,
): boolean;
export function recordMechanicalInspection(
  skill: Extract<MechanicalReadSkill, { kind: "inspection" }>,
  day: number,
  target: { readonly id: EntityId },
  result: Extract<InspectionResult, { kind: "role" }>,
  mayCommit?: () => boolean,
): boolean | void {
  // 默认纯数据入口保原完整调用，不查询新增 Reflect 或拒绝回调。
  if (!mayCommit) {
    (skill.history as Extract<MechanicalSkill, { kind: "inspection" }>["history"]).push({
      day,
      targetId: target.id,
      result: { ...result },
    });
    return;
  }
  // 受控首写保 history→push callee→target.id→result spread，再复验；使用原 history receiver。
  const history = skill.history as Extract<MechanicalSkill, { kind: "inspection" }>["history"];
  const append = history.push;
  const entry = {
    day,
    targetId: target.id,
    result: { ...result },
  };
  if (!mayCommit()) return false;
  Reflect.apply(append, history, [entry]);
  return true;
}
/** 原毒提案与标记之后提交库存消耗，不增加复检、回滚或新的付款时点。 */
export function consumeMechanicalPoison(
  skill: Extract<MechanicalReadSkill, { kind: "poison" }>,
): void {
  (skill as { remaining: 0 | 1 }).remaining = 0;
}
/** 调用方保留原攻击可空目标与完成顺序；非空目标标花费，空目标只按原机械首刀规则过期。 */
export function closeMechanicalExtraKnife(
  skill: Extract<MechanicalReadSkill, { kind: "wolf" }>,
  target: unknown,
): void {
  (skill as { extraKnife: "available" | "spent" | "expired" }).extraKnife = target
    ? "spent"
    : "expired";
}

/**
 * 单元测试：用真实 bootstrap、World、请求工厂和网关验证两族未付款行动退休。
 * 原组件引用、字面库存／事件／错误及手写回调轨迹是独立 oracle；不以生产资格函数生成预期。
 * 覆盖已退休原体、Provider 返回、晚目标 getter，以及已提交效果／镜像安装的失败前缀。
 * 两族使用各自合法六人板；只执行具体夜阶段，不运行完整周期、模型、传输或复现。
 */
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../src/app/bootstrap";
import { COMPONENT } from "../../../src/core/domain/components/names";
import { Phase, Role, type ActionProvider, type BoardConfig, type GameEvent, type ToolCall } from "../../../src/core/domain/model";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { retireRoleExecution } from "../../../src/core/domain/role-execution-authority";
import { GameActionRequestFactory } from "../../../src/game/engine/action_request_factory";
import { ToolGateway } from "../../../src/game/gateway/tool_gateway";
import type { NightStageContext } from "../../../src/game/mechanisms/stages/night/contracts";
import { bindNightAbilityActorQuery } from "../../../src/game/mechanisms/roles/night-ability-actors";
import { findNightAbility } from "../../../src/game/mechanisms/roles/abilities";
import { getDefaultRoleCatalog } from "../../../src/game/mechanisms/roles/role-catalog-assembly";
import { bindNativeNightFailurePolicy } from "../../../src/rulesets/native-night-failure-policy";
import { bindNativeNightTargetPolicy } from "../../../src/rulesets/native-night-target-policy";
import { bindNativeNightEffects } from "../../../src/rulesets/native-night-effects";
import { MECHANICAL_NIGHT_STAGES } from "../../../src/game/mechanisms/roles/mechanical_wolf/night_stages";
import { MECHANICAL_VALIDATION_RULES } from "../../../src/game/mechanisms/roles/mechanical_wolf/rules";
import { bindMechanicalSkill, captureMechanicalOwner, recordMechanicalModeScope } from "../../../src/game/mechanisms/roles/mechanical_wolf/night_scope";
import { getMechanicalState, learnMechanicalRole, selectMechanicalMode, recordMechanicalInspection } from "../../../src/game/mechanisms/roles/mechanical_wolf/state";
import { AWAKENED_NIGHT_STAGES } from "../../../src/game/mechanisms/roles/awakened_hidden_wolf/night_stages";
import { AWAKENED_VALIDATION_RULES } from "../../../src/game/mechanisms/roles/awakened_hidden_wolf/rules";
import { bindAwakenedSkill, captureAwakenedOwner, currentAwakenedNight } from "../../../src/game/mechanisms/roles/awakened_hidden_wolf/night_scope";
import { activateAwakenedLearning, getAwakenedState, learnAwakenedRole } from "../../../src/game/mechanisms/roles/awakened_hidden_wolf/state";
import { armAwakenedNativeGun } from "../../../src/game/mechanisms/roles/native-death-gun-resources";
import { sixPlayerMvpConfig } from "../../../src/runtime/scenarios/six_player_mvp";

type Family = "mechanical" | "awakened";
function fixture(family: Family) {
  const roles = [family === "mechanical" ? Role.MechanicalWolf : Role.AwakenedHiddenWolf,
    Role.Wolf, Role.Witch, Role.Guard, Role.Hunter, Role.Villager];
  const config: BoardConfig = {
    ...sixPlayerMvpConfig,
    roleSetups: roles.map((role) => ({ role, count: 1 })),
  };
  const game = bootstrapGame(config, { fixedRoles: roles });
  const role = game.world.getComponent(1, COMPONENT.Role)!;
  return family === "mechanical"
    ? { family: "mechanical" as const, game, role, state: getMechanicalState(role)! }
    : { family: "awakened" as const, game, role, state: getAwakenedState(role)! };
}
type Fixture = ReturnType<typeof fixture>;
function context(f: Fixture, getAction: ActionProvider["getAction"], day = 2): NightStageContext {
  const events: GameEvent[] = [], requests = new GameActionRequestFactory(f.game.world, events, day);
  return {
    world: f.game.world, events, currentDay: () => day, isCurrent: () => true,
    previousExile: null, roleCatalog: getDefaultRoleCatalog(), toolGateway: new ToolGateway(),
    get requestFactory() { return GameActionRequestFactory; },
    get nightActors() { return bindNightAbilityActorQuery(this.world); },
    get nativeNightFailure() { return bindNativeNightFailurePolicy(() => this.world); },
    get nativeNightTargets() { return bindNativeNightTargetPolicy(() => this); },
    get nativeNightEffects() { return bindNativeNightEffects(() => this); },
    actionProvider: { getAction },
    makeRequest: (actorId, allowedTools, extra) => requests.create({
      actorId, allowedTools, phase: Phase.Night, stage: extra.stage,
      requiresAction: extra.requiresAction ?? true,
      summary: { key: "request.summary.night_action" }, context: extra,
    }),
    getAliveByRole: (role) => f.game.world.getAliveEntityIds().filter((id) =>
      f.game.world.getComponent(id, COMPONENT.Role)?.role === role),
    ensureMarks: (id) => f.game.world.getComponent(id, COMPONENT.StatusMarks)!,
    pickMajorityTarget: () => null, shuffleWolves: (ids) => ids,
    state: { wolfChatOrder: [], endedWolves: new Set(), wolfVotes: {}, wolfTarget: null,
      seerChecks: [], poisonClaims: [], mechanicalEffects: { shields: [], attacks: [], failures: [] },
      awakenedEffects: { shields: [], attacks: [] } },
  };
}
const stage = (family: Family, id: string) =>
  (family === "mechanical" ? MECHANICAL_NIGHT_STAGES : AWAKENED_NIGHT_STAGES)
    .find((value) => value.id === id)!;
function owner(f: Fixture) {
  return f.family === "mechanical"
    ? captureMechanicalOwner(f.game.world, 1, () => true)!
    : captureAwakenedOwner(f.game.world, 1, () => true)!;
}
async function prepare(f: Fixture, ctx: NightStageContext, template: "witch" | "guard") {
  if (f.family === "mechanical") {
    expect(learnMechanicalRole(f.state, template === "witch" ? 3 : 4, template, 1)).toBe(true);
    expect(selectMechanicalMode(f.state, 2, "skill")).toBe(true);
    expect(recordMechanicalModeScope(f.game.world, captureMechanicalOwner(f.game.world, 1, () => true)!, 2)).toBe(true);
  } else {
    expect(learnAwakenedRole(f.state, template === "witch" ? 3 : 4, template, 1)).toBe(true);
    expect(activateAwakenedLearning(f.state, 1)).toBe(true);
    await stage("awakened", "awakened_opening").execute(ctx);
  }
}

test("两族退休原体仍满足纯当前性，但不能开出新请求或写入学习与模式", async () => {
  for (const family of ["mechanical", "awakened"] as const) {
    const f = fixture(family), scope = owner(f), before = JSON.stringify(f.state);
    let requests = 0;
    const ctx = context(f, async () => { requests++; return null; });
    retireRoleExecution(f.role);
    expect(scope.isCurrent()).toBe(true);
    expect(scope.canAct()).toBe(false);
    if (family === "mechanical") await stage(family, "mechanical_mode").execute(ctx);
    else {
      await stage(family, "awakened_opening").execute(ctx);
      expect(currentAwakenedNight(f.game.world, f.role)).toBeNull();
    }
    await stage(family, `${family}_mimic`).execute(ctx);
    expect(requests).toBe(0);
    expect(JSON.stringify(f.state)).toBe(before);
    expect(ctx.events).toEqual([]);
  }
});

test("机械 Provider 返回后退休不写默认模式，原当前性不被改变", async () => {
  const f = fixture("mechanical"), trace: string[] = [];
  const ctx = context(f, async () => {
    trace.push("provider"); retireRoleExecution(f.role); return null;
  });
  await stage("mechanical", "mechanical_mode").execute(ctx);
  expect(trace).toEqual(["provider"]);
  expect(f.state.learned).toBeNull();
  if (f.family !== "mechanical") throw new Error("fixture_family_mismatch");
  expect(f.state.mode).toBeNull();
  expect(owner(f).isCurrent()).toBe(true);
  expect(ctx.events).toEqual([]);
});

test("晚目标 getter 退休后两族拒绝首付款，getter 原异常仍优先传播", async () => {
  for (const family of ["mechanical", "awakened"] as const) {
    const f = fixture(family), trace: string[] = [], originalError = new Error("late_target_original");
    const call: ToolCall = family === "mechanical"
      ? { name: "mechanical_poison", args: { target_id: 6 } }
      : { name: "awakened_poison", args: { target_id: 6 } };
    const ctx = context(f, async () => call);
    await prepare(f, ctx, "witch");
    const validate = ctx.toolGateway.validateAndSanitize.bind(ctx.toolGateway);
    ctx.toolGateway.validateAndSanitize = (...args) => {
      const result = validate(...args);
      if (!result.sanitizedCall || !("target_id" in result.sanitizedCall.args))
        throw new Error("fixture_sanitized_target_missing");
      Object.defineProperty(result.sanitizedCall.args, "target_id", { configurable: true,
        get() {
          trace.push("target"); retireRoleExecution(f.role);
          // 两个独立轨迹：机械返回原 ID；觉醒在同一原读取点抛原 Error。
          if (family === "awakened") throw originalError;
          return 6;
        },
      });
      return result;
    };
    if (family === "mechanical") await stage(family, "mechanical_skill").execute(ctx);
    else await expect(stage(family, "awakened_skill").execute(ctx)).rejects.toBe(originalError);
    expect(trace).toEqual(["target"]);
    expect(owner(f).isCurrent()).toBe(true);
    expect(f.state.learned!.skill).toEqual({ kind: "poison", remaining: 1 });
    expect(f.state.skillClosedDay).toBeNull();
    expect(ctx.state.poisonClaims).toEqual([]);
    expect(ctx.events).toEqual([]);
    const validateRules = family === "mechanical" ? MECHANICAL_VALIDATION_RULES : AWAKENED_VALIDATION_RULES;
    expect(validateRules[call.name]!({ world: ctx.world, roleCatalog: ctx.roleCatalog, actorId: 1,
      role: f.role, day: 2, phase: Phase.Night, toolCall: call })).toEqual({
      code: family === "mechanical" ? RuleError.MechanicalUnavailable : RuleError.AwakenedUnavailable,
    });
  }
});

